#pragma once
#include <cmath>
#include <stdexcept>
namespace glasshelix::reduction { struct reduction_result {double aggregate,derivative,reporter_correlation;bool closed;}; inline reduction_result evaluate(double a,double b,double ra,double rb,double reporter){if(!std::isfinite(a+b+ra+rb+reporter))throw std::invalid_argument("nonfinite supplied regime");return {a+b,ra*a+rb*b,reporter,ra==rb};} enum class threshold_result{pass,fail,unresolved}; struct error_report{double conversion=0,integration=0,dropped_support=0,empirical=0,certified=0,scientific=0;bool justified=false;}; inline threshold_result assess(error_report e,double t){if(e.certified<0||!std::isfinite(e.certified)||t<0)throw std::invalid_argument("invalid bound");if(!e.justified)return threshold_result::unresolved;return e.certified<=t?threshold_result::pass:threshold_result::fail;} }
